      "identity": {
        "type": "string",
        "title": "Named-user identity",
        "description": "Confirm the simple first-release identity approach; no SSO.",
        "oneOf": [
          {
            "const": "simple_named_login",
            "title": "Simple named-user login (recommended)"
          },
          {
            "const": "shared_access",
            "title": "Shared/kiosk access"
          },
          {
            "const": "other",
            "title": "Other"
          }
        ],
        "default": "simple_named_login"
      },
      "checkout_speed": {
        "type": "string",
        "title": "Speed target",
        "description": "What should the PRD test for the common authenticated checkout/return path?",
        "oneOf": [
          {
            "const": "under_10_seconds",
            "title": "Under 10 seconds after equipment selection"
          },
          {
            "const": "under_30_seconds",
            "title": "Under 30 seconds"
          },
          {
            "const": "qualitative",
            "title": "Fast/usability target without a numeric threshold"
          },
          {
            "const": "other",
            "title": "Other"
          }
        ],
        "default": "under_10_seconds"
      },
      "due_date": {
        "type": "string",
        "title": "Due-date default",
        "oneOf": [
          {
            "const": "tomorrow_editable",
            "title": "Default to tomorrow, editable (approved decision)"
          },
          {
            "const": "required_manual",
            "title": "Always require manual date selection"
          },
          {
            "const": "other",
            "title": "Other"
          }
        ],
        "default": "tomorrow_editable"
      },
      "mvp_cuts": {
        "type": "string",
        "title": "MVP cuts and test data",
        "description": "Confirm any explicit cuts: in-app due/overdue only (no WhatsApp/email), no GPS/offline/maintenance/missing-incident workflow, survey-kit shortcut optional if safe. Also state whether deterministic demo data is acceptable.",
        "default": "Use approved decisions: in-app status only; defer messaging, GPS, offline sync, maintenance, full missing incidents; include deterministic local demo data."
      }
    }
  }
